#include <string>

using namespace std;

const int MAXN = 66;

int r, c, n;
string s;
long long comb[MAXN][MAXN];

int a_count[MAXN], b_count[MAXN];
vector<long long> partials_list[MAXN], partials_zero_list[MAXN];

void generate_combinations() {
    for (int i = 0; i <= n; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
    }
}

long long compute_diff(int conf, int a_prev, int b_prev) {
    long long total_diff = 0;
    for (int i = 0; i <= c; ++i) {
        if (conf & (1 << i)) {
            b_prev++;
            total_diff -= comb[b_prev - 1][r - 1] * (comb[n - b_prev][r] - comb[a_prev][r]);
        } else {
            a_prev++;
            total_diff += comb[a_prev - 1][r - 1] * (comb[n - a_prev][r] - comb[b_prev][r]);
        }
    }
    return total_diff;
}

bool check_configuration(int conf) {
    for (int i = 0; i <= c; ++i) {
        if (s[2 * r + c + i] == 'A' && ((conf >> i) & 1) == 1) return false;
        if (s[2 * r + c + i] == 'B' && ((conf >> i) & 1) == 0) return false;
    }
    return true;
}

void process_second_part() {
    int total_conf = 1 << (c + 1);
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_cnt = __builtin_popcount(conf);
        int a_cnt = c + 1 - b_cnt;
        if (check_configuration(conf))
            partials_list[a_cnt].push_back(compute_diff(conf, r + c - a_cnt, r + c - b_cnt));
        else
            partials_zero_list[a_cnt].push_back(compute_diff(conf, r + c - a_cnt, r + c - b_cnt));
    }
    for (int i = 0; i <= c + 1; ++i) {
        sort(partials_list[i].begin(), partials_list[i].end());
        sort(partials_zero_list[i].begin(), partials_zero_list[i].end());
    }
}

long long count_occurrences(const vector<long long>& data, long long val) {
    auto low = lower_bound(data.begin(), data.end(), val);
    auto up = upper_bound(data.begin(), data.end(), val);
    return up - low;
}

long long solve() {
    int total_conf = 1 << (c + 1);
    pair<long long, long long> answer = {1LL << 60, 0};
    for (int conf = 0; conf < total_conf; ++conf) {
        int b_cnt = __builtin_popcount(conf);
        int a_cnt = c + 1 - b_cnt;
        long long act = compute_diff(conf, r - 1, r - 1);
        long long coef = get_coefficient(conf);
        auto it = lower_bound(partials_list[c + 1 - a_cnt].begin(), partials_list[c + 1 - a_cnt].end(), -act);
        if (it != partials_list[c + 1 - a_cnt].end()) {
            if (answer.first >= abs(*it + act)) {
                long long count = count_occurrences(partials_list[c + 1 - a_cnt], *it);
                update_pair(answer, {abs(*it + act), coef * count});
            }
        }
        if (it != partials_list[c + 1 - a_cnt].begin()) {
            it--;
            if (answer.first >= abs(*it + act)) {
                long long count = count_occurrences(partials_list[c + 1 - a_cnt], *it);
                update_pair(answer, {abs(*it + act), coef * count});
            }
        }
        long long zero_coef = 0;
        auto it_zero = lower_bound(partials_zero_list[c + 1 - a_cnt].begin(), partials_zero_list[c + 1 - a_cnt].end(), -act);
        if (it_zero != partials_zero_list[c + 1 - a_cnt].end()) {
            long long count = count_occurrences(partials_list[c + 1 - a_cnt], *it_zero);
            if (answer.first >= abs(*it_zero + act))
                update_pair(answer, {abs(*it_zero + act), zero_coef * count});
        }
        if (it_zero != partials_zero_list[c + 1 - a_cnt].begin()) {
            it_zero--;
            long long count = count_occurrences(partials_list[c + 1 - a_cnt], *it_zero);
            if (answer.first >= abs(*it_zero + act))
                update_pair(answer, {abs(*it_zero + act), zero_coef * count});
        }
    }
    return answer.second;
}

int main() {
    cin >> r >> c >> s;
    n = 2 * (r + c);
    generate_combinations();
    for (int i = 1; i <= n; ++i) {
        a_count[i] = a_count[i - 1] + (s[i - 1] == 'A' ? 1 : 0);
        b_count[i] = b_count[i - 1] + (s[i - 1] == 'B' ? 1 : 0);
